import XCTest
@testable import Screener

/// RTCP builders against ScreenerTests/Fixtures/rtcp.json (generated by the
/// reference's rtcp.build_* with the args recorded next to each result).
final class RTCPTests: XCTestCase {
    private var f: [String: Any] = [:]

    override func setUpWithError() throws { f = try Fixture.load("rtcp") }

    private func entry(_ key: String) -> (args: [String: Any], result: String) {
        let e = f[key] as! [String: Any]
        return (e["args"] as! [String: Any], e["result"] as! String)
    }

    /// Fixture SSRCs are either JSON ints or "0x…" strings.
    private func u32(_ v: Any?) -> UInt32 {
        if let s = v as? String { return UInt32(s.dropFirst(2), radix: 16)! }
        return UInt32(v as! Int)
    }

    func testFIRLegacy() {
        let (a, r) = entry("build_fir_legacy")
        XCTAssertEqual(RTCP.firLegacy(targetSSRC: u32(a["target_ssrc"])).hex, r)
    }

    func testFIR() {
        let (a, r) = entry("build_fir")
        let pkt = RTCP.fir(senderSSRC: u32(a["sender_ssrc"]), targetSSRC: u32(a["target_ssrc"]),
                           seq: UInt8(a["seq_nr"] as! Int))
        XCTAssertEqual(pkt.hex, r)
    }

    func testPLI() {
        let (a, r) = entry("build_pli")
        XCTAssertEqual(RTCP.pli(senderSSRC: u32(a["sender_ssrc"]), mediaSSRC: u32(a["media_ssrc"])).hex, r)
    }

    func testNACK() {
        let (a, r) = entry("build_nack")
        let lost = (a["lost_seqs"] as! [Int]).map { UInt16($0) }
        let pkt = RTCP.nack(senderSSRC: u32(a["sender_ssrc"]), mediaSSRC: u32(a["media_ssrc"]), lostSeqs: lost)
        XCTAssertEqual(pkt.hex, r)
    }

    func testNACKEmptyAndWrapCoalescing() {
        XCTAssertEqual(RTCP.nack(senderSSRC: 1, mediaSSRC: 2, lostSeqs: []), Data())
        // 65535 and 0 are 1 apart mod 2^16 but sorted() puts 0 first: two FCIs, as in Python.
        let pkt = RTCP.nack(senderSSRC: 1, mediaSSRC: 2, lostSeqs: [0xFFFF, 0, 1, 18])
        XCTAssertEqual(pkt.hex, "81cd0005" + "00000001" + "00000002" + "00000001" + "0012" + "0000" + "ffff" + "0000")
    }

    func testReceiverReport() {
        let (a, r) = entry("build_rr")
        let sources = (a["source_ssrcs"] as! [Any]).map { u32($0) }
        let statsIn = a["ssrc_stats"] as! [String: [String: Int]]
        var stats: [UInt32: RTCP.SourceStats] = [:]
        for (k, v) in statsIn { stats[u32(k)] = .init(maxSeq: UInt16(v["max_seq"]!), roc: UInt32(v["roc"]!)) }
        let pkt = RTCP.receiverReport(senderSSRC: u32(a["sender_ssrc"]), sources: sources, stats: stats)
        XCTAssertEqual(pkt.hex, r)
    }

    func testEmptyReceiverReportIsOneWord() {
        XCTAssertEqual(RTCP.receiverReport(senderSSRC: 0x0102_0304).hex, "80c9000101020304")
    }

    func testReceiverReportLSRAndDLSR() {
        let arrival = Date(timeIntervalSince1970: 1000)
        let now = arrival.addingTimeInterval(0.5)
        let pkt = RTCP.receiverReport(senderSSRC: 1, sources: [7], stats: [:],
                                      srData: [7: .init(lsr: 0xAABB_CCDD, arrival: arrival)], now: now)
        // Block: ssrc | lost | ext seq | jitter | LSR | DLSR (0.5 s × 65536 = 0x8000)
        XCTAssertEqual(pkt.hex, "81c90007" + "00000001" + "00000007" + "00000000" + "00000000" + "00000000"
                       + "aabbccdd" + "00008000")
    }

    func testReceiverReportCapsAt31Blocks() {
        let pkt = RTCP.receiverReport(senderSSRC: 1, sources: (0..<40).map { UInt32($0) })
        XCTAssertEqual(pkt[0], 0x80 | 31)
        XCTAssertEqual(pkt.count, 8 + 31 * 24)
    }

    func testAppLTR() {
        let (a, r) = entry("build_rtcp_app_ltrp")
        let pkt = RTCP.appLTR(senderSSRC: u32(a["sender_ssrc"]), ltrID: u32(a["ltr_id"]))
        XCTAssertEqual(pkt.hex, r)
    }

    /// RCTL layout from AVConference's VCMediaControlInfoSerializeWithData
    /// (type 2, 20-byte info) inside the "RCTL" APP: 32 bytes, length field 7.
    func testAppRCTLLayout() {
        let pkt = RTCP.appRCTL(senderSSRC: 0x4014_2F36, echo: 0xA1B2, echoDelayMs: 0x0012, now1024: 0x3456,
                               owrd: 0x0001, burstyLoss: 20, lossField: 0x1ABC, bwe: 60_000)
        XCTAssertEqual(pkt.count, 32)
        XCTAssertEqual(pkt.hex, "80cc0007" + "40142f36" + "5243544c"
                       + "85000004" + "a1b2" + "00000000" + "0012" + "3456" + "0001"
                       + "fabc"          // burstyLoss clamped to 15 << 12 | 0xABC
                       + "ea60")         // 60000
        XCTAssertTrue(RTCP.isRTCP(pkt))
        XCTAssertEqual(RTCP.packetTypes(pkt), [204])
    }

    /// What MediaTransport sends for a tick with a 3-packet loss burst, 7 %
    /// windowed loss and the 30 Mbps start estimate.
    func testAppRCTLWithAdaptiveLossFields() {
        let pkt = RTCP.appRCTL(senderSSRC: 0x4014_2F36, echo: 0x4536, echoDelayMs: 3, now1024: 0x0400,
                               burstyLoss: 3, lossField: 7, bwe: 30_000)
        XCTAssertEqual(Data(pkt.suffix(4)).hex, "3007" + "7530")
    }

    func testReceiverReportLossWord() {
        let pkt = RTCP.receiverReport(senderSSRC: 1, sources: [7, 8],
                                      loss: [7: .init(fractionLost: 25, cumulativeLost: 10)],
                                      now: Date(timeIntervalSince1970: 0))
        XCTAssertEqual(pkt.subdata(in: 12..<16).hex, "1900000a")
        XCTAssertEqual(pkt.subdata(in: 36..<40).hex, "00000000", "a source without stats reports zero")
    }

    func testEmptySenderReportLayout() {
        let now = Date(timeIntervalSince1970: 1_700_000_000.25)
        let pkt = RTCP.emptySR(senderSSRC: 0xDEAD_BEEF, now: now)
        XCTAssertEqual(pkt.count, 28)
        XCTAssertEqual(pkt.prefix(8).hex, "80c80006deadbeef")
        let ntpSec = UInt32(1_700_000_000 + 2_208_988_800)
        XCTAssertEqual(pkt.subdata(in: 8..<12).hex, String(format: "%08x", ntpSec))
        XCTAssertEqual(pkt.subdata(in: 12..<16).hex, "40000000")    // .25 × 2^32
        XCTAssertEqual(pkt.suffix(8).hex, "0000000000000000")
    }

    func testCompoundWithRRPrefixesEmptyRR() {
        let pli = RTCP.pli(senderSSRC: 1, mediaSSRC: 2)
        XCTAssertEqual(RTCP.compoundWithRR(senderSSRC: 1, payload: pli).hex, "80c9000100000001" + pli.hex)
    }

    func testParseSRArrivalsWalksCompound() {
        let arrival = Date(timeIntervalSince1970: 5)
        // RR (2 words) + SR from 0x11223344 with NTP 0x0001AAAA.BBBB0000 + trailing junk.
        let rr = Data(hex: "80c9000100000001")
        let sr = Data(hex: "80c80006" + "11223344" + "0001aaaa" + "bbbb0000" + "00000000" + "00000000" + "00000000")
        let out = RTCP.parseSRArrivals(rr + sr + Data([0x80]), now: arrival)
        XCTAssertEqual(out.count, 1)
        XCTAssertEqual(out.first?.ssrc, 0x1122_3344)
        XCTAssertEqual(out.first?.ntpMid32, 0xAAAA_BBBB)
        XCTAssertEqual(out.first?.arrival, arrival)
        // A length field running past the buffer stops the walk.
        XCTAssertTrue(RTCP.parseSRArrivals(Data(hex: "80c8ffff11223344"), now: arrival).isEmpty)
    }

    func testPacketTypesWalksCompound() {
        let rr = Data(hex: "80c9000100000001")
        let sr = Data(hex: "80c80006" + "11223344" + "0001aaaa" + "bbbb0000" + "00000000" + "00000000" + "00000000")
        let app = RTCP.appLTR(senderSSRC: 1, ltrID: 7)
        XCTAssertEqual(RTCP.packetTypes(rr + sr + app + Data([0x80])), [201, 200, 204])
        XCTAssertEqual(RTCP.packetTypes(Data(hex: "80c8ffff11223344")), [], "a length past the buffer stops the walk")
    }

    func testClassification() {
        XCTAssertTrue(RTCP.isRTCP(Data([0x80, 200])))
        XCTAssertTrue(RTCP.isRTCP(Data([0x81, 207])))
        XCTAssertFalse(RTCP.isRTCP(Data([0x80, 208])))
        XCTAssertFalse(RTCP.isRTCP(Data([0x80, 100])))          // HEVC RTP
        XCTAssertFalse(RTCP.isRTCP(Data([0x80, 0x80 | 100])))   // HEVC RTP with marker
        XCTAssertFalse(RTCP.isRTCP(Data([0x80, 101])))          // AAC-ELD RTP
        XCTAssertFalse(RTCP.isRTCP(Data([0x00, 200])))          // not version 2
        XCTAssertFalse(RTCP.isRTCP(Data([0x80])))
    }
}
